function drawerHead(title,sub){return L.tpl`<div class="drawer-head"><div><h2>${h(title)}</h2><p class="sub">${h(sub)}</p></div><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>`;}
function openSKU(key){L.setDialogRefresh(()=>openSKU(key));
 const r=S.rows.find(r=>r.key===key);if(!r)return;
 const steps=[[L.s('Прогноз за ')+r.horizon+L.s(' дней'),fmt(r.demand,1)+L.s(' шт.')],[L.s('Страховой запас · ')+r.safety+L.s(' дней'),'+ '+fmt(r.buffer,1)],[L.s('Доступный остаток'),'− '+fmt(r.stock,1)],[L.s('Учтённые поставки'),'− '+fmt(r.transit,1)],[L.s('Потребность до округления'),fmt(r.net,1)],[L.s('Минимальная партия / кратность'),fmt(r.minQty)+' / '+fmt(r.multiple)]];
 openDialog(drawerHead(r.sku,r.name)+L.tpl`<div class="drawer-body"><div class="detail-chips">${status(r)}<span class="badge">${h(r.supplier)}</span><span class="badge">${h(r.category)}</span><span class="badge">Код 1С: ${h(r.code)}</span></div><div class="kpis">${kpi(L.s('Заказать'),fmt(qty(r)),L.s('шт.'),L.s('По текущей рекомендации'),'box')}${kpi(L.s('Запас на'),r.cover===null?'—':fmt(r.cover),L.s('дн.'),L.s('Без учёта поступлений'),'chart')}${kpi(L.s('Оценка суммы'),value(r)===null?'—':compact(value(r)),h(S.cfg.currency),L.s('По себестоимости'),'suppliers')}</div><section class="card"><div class="card-head"><h2>Спрос по артикулу</h2></div><div class="chart-wrap">${chart([r],true)}</div><p class="chart-note">Бледные столбцы — факт; зелёная линия — скорректированный спрос; пунктир — прогноз. * Неполные месяцы горизонта.</p></section><section class="card"><div class="card-head" style="padding-bottom:12px"><h2>Из чего складывается заказ</h2></div>${steps.map(([l,v])=>`<div class="calc-row"><span>${l}</span><strong>${v}</strong></div>`).join('')}<div class="calc-row total"><span>Рекомендованный заказ</span><strong>${fmt(r.order)} шт.</strong></div></section><div class="detail-chips"><span class="badge">Сезонность ×${fmt(r.seasonalFactor,2)}</span><span class="badge">Тренд ${fmt(r.trend*100)}%</span><span class="badge">Плановый рост ${fmt(r.planned*100)}%</span><span class="badge">Категория ×${fmt(r.mult,2)}</span></div><p class="mini-note">Исключено из истории: ${fmt(r.excludedQty)} шт. Компенсировано упущенного спроса в истории: ${fmt(r.lostQty)} шт. Это исторические поправки, не прямые добавки к заказу.</p>${r.uncertain||r.late||r.overdue?L.tpl`<div class="notice">${icon('alert')}<span>В пути без даты: ${fmt(r.uncertain)}; после горизонта: ${fmt(r.late)}; просрочено: ${fmt(r.overdue)} шт. По умолчанию эти объёмы не уменьшают заказ.</span></div>`:''}${masterFields(r)}<section class="form-section"><h3>Что изменится, если…</h3><div class="form-grid three"><label class="field">Остаток, шт.<input id="sim-stock" type="number" min="0" value="${r.stock??0}"></label><label class="field">Учтено в пути, шт.<input id="sim-transit" type="number" min="0" value="${r.transit}"></label><label class="field">Поставка, дней<input id="sim-lead" type="number" min="1" max="365" value="${r.lead}"></label></div><button class="btn" style="margin-top:14px" data-sim="${key}">${icon('sliders')}Проверить сценарий</button><div id="sim-result"></div><p class="mini-note">Сценарий не меняет основной расчёт и экспорт. Измените общие параметры или вручную скорректируйте количество ниже.</p></section>${r.anomalies.length?L.tpl`<section class="card"><div class="card-head" style="padding-bottom:13px"><h2>Кандидаты на аномалии · ${r.anomalies.length}</h2></div>${r.anomalies.slice(0,15).map(a=>L.tpl`<div class="anomaly-row"><span>${niceDate(a.date)} · ${h(L.message(a.reason))}</span><b>${fmt(a.qty)} шт.</b></div>`).join('')}<p class="mini-note" style="padding:0 17px">${S.cfg.outliers?L.s('Исключение включено.'):L.s('Исключение выключено.')} Проверяйте крупные заказы перед подтверждением. Показано до 15 событий.</p></section>`:''}<section class="form-section"><h3>Корректировка менеджера</h3><div class="form-grid"><label class="field">Количество к заказу, шт.<input id="manual-qty" type="number" min="0" step="1" value="${qty(r)??''}"><small>0 — не заказывать. Соблюдайте кратность ${r.multiple}.</small></label><div style="align-self:center"><button class="btn btn-primary" data-manual="${key}">Сохранить количество</button></div></div></section>${r.quality.length?`<section class="card"><div class="warning-list">${r.quality.map(q=>`<div class="warning-item">${icon('info')}<span>${h(L.message(q))}</span></div>`).join('')}</div></section>`:''}</div><div class="drawer-bottom"><button class="btn" data-action="close">Закрыть карточку</button></div>`);
}
